-- Initial normalized marketplace schema. Generated from prisma/schema.prisma.
CREATE TABLE `User` (`id` VARCHAR(191) NOT NULL, `email` VARCHAR(191) NOT NULL, `passwordHash` VARCHAR(255) NOT NULL, `firstName` VARCHAR(100) NULL, `lastName` VARCHAR(100) NULL, `role` ENUM('CUSTOMER','SELLER','ADMIN') NOT NULL DEFAULT 'CUSTOMER', `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `User_email_key`(`email`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `Seller` (`id` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `storeName` VARCHAR(191) NOT NULL, `slug` VARCHAR(191) NOT NULL, `description` TEXT NULL, `status` ENUM('PENDING','ACTIVE','SUSPENDED') NOT NULL DEFAULT 'PENDING', `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `Seller_userId_key`(`userId`), UNIQUE INDEX `Seller_storeName_key`(`storeName`), UNIQUE INDEX `Seller_slug_key`(`slug`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `Category` (`id` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `slug` VARCHAR(191) NOT NULL, `parentId` VARCHAR(191) NULL, `imageUrl` VARCHAR(2048) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `Category_slug_key`(`slug`), INDEX `Category_parentId_idx`(`parentId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `Product` (`id` VARCHAR(191) NOT NULL, `sellerId` VARCHAR(191) NOT NULL, `categoryId` VARCHAR(191) NOT NULL, `title` VARCHAR(255) NOT NULL, `slug` VARCHAR(191) NOT NULL, `description` TEXT NOT NULL, `brand` VARCHAR(191) NULL, `basePrice` DECIMAL(12,2) NOT NULL, `currency` CHAR(3) NOT NULL DEFAULT 'USD', `stockQuantity` INTEGER NOT NULL DEFAULT 0, `status` ENUM('DRAFT','ACTIVE','ARCHIVED') NOT NULL DEFAULT 'DRAFT', `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `Product_slug_key`(`slug`), INDEX `Product_categoryId_status_idx`(`categoryId`,`status`), INDEX `Product_sellerId_status_idx`(`sellerId`,`status`), INDEX `Product_brand_idx`(`brand`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `ProductVariant` (`id` VARCHAR(191) NOT NULL, `productId` VARCHAR(191) NOT NULL, `sku` VARCHAR(191) NOT NULL, `price` DECIMAL(12,2) NULL, `stockQuantity` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `ProductVariant_sku_key`(`sku`), INDEX `ProductVariant_productId_idx`(`productId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `ProductImage` (`id` VARCHAR(191) NOT NULL, `productId` VARCHAR(191) NOT NULL, `variantId` VARCHAR(191) NULL, `url` VARCHAR(2048) NOT NULL, `altText` VARCHAR(255) NULL, `position` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `ProductImage_productId_position_idx`(`productId`,`position`), INDEX `ProductImage_variantId_idx`(`variantId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `Attribute` (`id` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `code` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `Attribute_name_key`(`name`), UNIQUE INDEX `Attribute_code_key`(`code`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE `ProductAttribute` (`id` VARCHAR(191) NOT NULL, `productId` VARCHAR(191) NOT NULL, `attributeId` VARCHAR(191) NOT NULL, `value` VARCHAR(500) NOT NULL, INDEX `ProductAttribute_attributeId_value_idx`(`attributeId`,`value`), UNIQUE INDEX `ProductAttribute_productId_attributeId_key`(`productId`,`attributeId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

