CREATE TABLE `Order` (`id` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `status` ENUM('PENDING','PAID','PROCESSING','SHIPPED','DELIVERED','CANCELLED','REFUNDED') NOT NULL DEFAULT 'PENDING', `currency` CHAR(3) NOT NULL DEFAULT 'USD', `subtotalAmount` DECIMAL(12,2) NOT NULL, `shippingAmount` DECIMAL(12,2) NOT NULL DEFAULT 0, `taxAmount` DECIMAL(12,2) NOT NULL DEFAULT 0, `totalAmount` DECIMAL(12,2) NOT NULL, `shippingAddress` JSON NOT NULL, `paymentProvider` VARCHAR(50) NULL, `paymentRef` VARCHAR(191) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, INDEX `Order_userId_createdAt_idx`(`userId`,`createdAt`), INDEX `Order_status_createdAt_idx`(`status`,`createdAt`), UNIQUE INDEX `Order_paymentProvider_paymentRef_key`(`paymentProvider`,`paymentRef`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

